-- Canonical progression for every live performance. Festival settlement is only a caller.
CREATE TABLE public.live_performance_outcomes (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_type text NOT NULL CHECK(source_type IN('ordinary_gig','festival_performance')),
 source_id uuid NOT NULL, performance_outcome_id uuid, band_id uuid NOT NULL REFERENCES public.bands(id), city_id uuid REFERENCES public.cities(id), country text,
 subject_type text NOT NULL DEFAULT 'band', subject_id uuid NOT NULL, stable_reference text NOT NULL UNIQUE,
 before_state jsonb NOT NULL, validated_change jsonb NOT NULL, after_state jsonb NOT NULL, evidence jsonb NOT NULL,
 evidence_digest text NOT NULL, rules_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_type,source_id)
);
CREATE TABLE public.band_fan_progression_events (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_type text NOT NULL, source_id uuid NOT NULL, performance_outcome_id uuid NOT NULL REFERENCES public.live_performance_outcomes(id),
 subject_type text NOT NULL, subject_id uuid NOT NULL, stable_reference text NOT NULL UNIQUE, before_state jsonb NOT NULL, validated_change jsonb NOT NULL,
 after_state jsonb NOT NULL, evidence_digest text NOT NULL, rules_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.band_fame_progression_events (LIKE public.band_fan_progression_events INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES);
CREATE TABLE public.member_xp_transactions (LIKE public.band_fan_progression_events INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES);
ALTER TABLE public.member_xp_transactions ADD COLUMN user_id uuid NOT NULL REFERENCES auth.users(id);
CREATE TABLE public.song_performance_progression_events (LIKE public.band_fan_progression_events INCLUDING DEFAULTS INCLUDING CONSTRAINTS INCLUDING INDEXES);
ALTER TABLE public.song_performance_progression_events ADD COLUMN progression_type text NOT NULL CHECK(progression_type IN('familiarity','popularity'));
ALTER TABLE public.live_performance_outcomes ENABLE ROW LEVEL SECURITY; ALTER TABLE public.band_fan_progression_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.band_fame_progression_events ENABLE ROW LEVEL SECURITY; ALTER TABLE public.member_xp_transactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.song_performance_progression_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.live_performance_outcomes,public.band_fan_progression_events,public.band_fame_progression_events,public.member_xp_transactions,public.song_performance_progression_events FROM PUBLIC,anon,authenticated;

-- One transaction locks the effect, canonical event and affected projection. Requested deltas are never trusted.
CREATE OR REPLACE FUNCTION public._apply_live_performance_progression(
 p_effect_id uuid,p_settlement_id uuid,p_outcome_id uuid,p_subject_type text,p_subject_id text,p_stable_reference text,p_requested_payload jsonb,p_kind text,p_authority text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE c jsonb;o jsonb;ev jsonb;perf public.festival_runtime_performances%ROWTYPE;lo public.live_performance_outcomes%ROWTYPE;
 b public.bands%ROWTYPE; eid uuid; score numeric; audience int; delta int; casual int; dedicated int; super int; profile public.profiles%ROWTYPE;
 before jsonb;change jsonb;after jsonb;digest text; table_name text; record_type text; song uuid; old_value int; member_user uuid; city uuid; country_name text; attendance text;
BEGIN
 c:=public._festival_effect_authority_context(p_effect_id,p_settlement_id,p_outcome_id,p_subject_type,p_subject_id,p_stable_reference,p_requested_payload,p_kind);
 o:=c->'outcome'; digest:=encode(digest(((o->'evidence_references')||jsonb_build_object('rulesVersion',o->>'rules_version'))::text,'sha256'),'hex');
 SELECT * INTO perf FROM public.festival_runtime_performances WHERE id=(o#>>'{evidence_references,performanceSessionId}')::uuid AND status='completed' FOR SHARE;
 IF perf.id IS NULL THEN PERFORM public._festival_edition_settlement_error('FESTIVAL_EFFECT_IMMUTABLE_EVIDENCE_MISSING'); END IF;
 score:=coalesce(perf.performance_score,(o->>'final_score')::numeric,0); audience:=greatest(0,coalesce(perf.estimated_audience,(o#>>'{evidence_references,estimatedAudience}')::int,0));
 SELECT (o#>>'{evidence_references,cityId}')::uuid,o#>>'{evidence_references,country}' INTO city,country_name;
 SELECT * INTO lo FROM public.live_performance_outcomes WHERE source_type='festival_performance' AND source_id=perf.id;
 IF lo.id IS NULL THEN
  INSERT INTO public.live_performance_outcomes(source_type,source_id,band_id,city_id,country,subject_id,stable_reference,before_state,validated_change,after_state,evidence,evidence_digest,rules_version)
  VALUES('festival_performance',perf.id,perf.band_id,city,country_name,perf.band_id,'festival-performance:'||perf.id||':performance_result:'||perf.band_id,'{}','{}','{}',
   jsonb_build_object('score',score,'audience',audience,'completedSongIds',coalesce(o#>'{evidence_references,performedSongIds}','[]'),'attendingMembers',(SELECT coalesce(jsonb_agg(jsonb_build_object('profileId',a.profile_id,'status',a.status)),'[]') FROM public.festival_runtime_band_member_attendance a WHERE a.runtime_performance_id=perf.id),'stageId',perf.runtime_stage_id,'billing',coalesce(o#>'{evidence_references,billing}','null'),'crowdResponse',perf.crowd_response),digest,o->>'rules_version') RETURNING * INTO lo;
 END IF;
 IF lo.evidence_digest<>digest OR lo.band_id<>perf.band_id THEN PERFORM public._festival_edition_settlement_error('FESTIVAL_EFFECT_CANONICAL_STATE_MISMATCH'); END IF;
 IF p_kind='performance_result' THEN eid:=lo.id;before:='{}';change:='{}';after:='{}';table_name:='live_performance_outcomes';record_type:='performance_outcome';
 ELSE
  SELECT * INTO b FROM public.bands WHERE id=perf.band_id FOR UPDATE;
  IF p_kind='band_fans' THEN
   SELECT id INTO eid FROM public.band_fan_progression_events WHERE stable_reference=p_stable_reference;
   IF eid IS NULL THEN
    delta:=least(1000000,greatest(0,floor(audience*.02*(1+least(25,score/4)/25)*greatest(.3,1-coalesce(b.fame,0)/10000.0))));
    super:=floor(delta*(CASE WHEN score/4>=22 THEN .15 WHEN score/4>=16 THEN .05 ELSE .02 END)); dedicated:=floor(delta*(CASE WHEN score/4>=22 THEN .35 WHEN score/4>=16 THEN .25 ELSE .10 END)); casual:=delta-super-dedicated;
    before:=jsonb_build_object('total',coalesce(b.total_fans,0),'casual',coalesce(b.casual_fans,0),'dedicated',coalesce(b.dedicated_fans,0),'superfans',coalesce(b.superfans,0)); change:=jsonb_build_object('total',delta,'casual',casual,'dedicated',dedicated,'superfans',super);
    UPDATE public.bands SET total_fans=coalesce(total_fans,0)+delta,casual_fans=coalesce(casual_fans,0)+casual,dedicated_fans=coalesce(dedicated_fans,0)+dedicated,superfans=coalesce(superfans,0)+super WHERE id=b.id;
    IF country_name IS NOT NULL THEN INSERT INTO public.band_country_fans(band_id,country,total_fans,casual_fans,dedicated_fans,superfans,last_activity_date) VALUES(b.id,country_name,delta,casual,dedicated,super,now()) ON CONFLICT(band_id,country) DO UPDATE SET total_fans=band_country_fans.total_fans+delta,casual_fans=band_country_fans.casual_fans+casual,dedicated_fans=band_country_fans.dedicated_fans+dedicated,superfans=band_country_fans.superfans+super,last_activity_date=now(); END IF;
    IF city IS NOT NULL THEN INSERT INTO public.band_city_fans(band_id,city_id,city_name,country,total_fans,casual_fans,dedicated_fans,superfans) VALUES(b.id,city,coalesce((SELECT name FROM public.cities WHERE id=city),'Unknown'),country_name,delta,casual,dedicated,super) ON CONFLICT(band_id,city_id) DO UPDATE SET total_fans=band_city_fans.total_fans+delta,casual_fans=band_city_fans.casual_fans+casual,dedicated_fans=band_city_fans.dedicated_fans+dedicated,superfans=band_city_fans.superfans+super;
    END IF; after:=jsonb_build_object('total',coalesce(b.total_fans,0)+delta,'casual',coalesce(b.casual_fans,0)+casual,'dedicated',coalesce(b.dedicated_fans,0)+dedicated,'superfans',coalesce(b.superfans,0)+super);
    INSERT INTO public.band_fan_progression_events(source_type,source_id,performance_outcome_id,subject_type,subject_id,stable_reference,before_state,validated_change,after_state,evidence_digest,rules_version) VALUES('festival_performance',perf.id,lo.id,'band',b.id,p_stable_reference,before,change,after,digest,lo.rules_version) RETURNING id INTO eid;
   ELSE SELECT before_state,validated_change,after_state INTO before,change,after FROM public.band_fan_progression_events WHERE id=eid; IF (after->>'total')::int<>coalesce(b.total_fans,0) THEN PERFORM public._festival_edition_settlement_error('FESTIVAL_EFFECT_CANONICAL_STATE_MISMATCH'); END IF; END IF; table_name:='band_fan_progression_events';record_type:='fan_event';
  ELSIF p_kind='band_fame' THEN
   SELECT id,before_state,validated_change,after_state INTO eid,before,change,after FROM public.band_fame_progression_events WHERE stable_reference=p_stable_reference;
   IF eid IS NULL THEN delta:=least(20,greatest(-10,round((score-55)/10)+(CASE WHEN audience>=5000 THEN 2 WHEN audience>=1000 THEN 1 ELSE 0 END)));before:=jsonb_build_object('fame',coalesce(b.fame,0));change:=jsonb_build_object('fame',delta);after:=jsonb_build_object('fame',greatest(0,coalesce(b.fame,0)+delta));UPDATE public.bands SET fame=(after->>'fame')::int WHERE id=b.id;INSERT INTO public.band_fame_history(band_id,city_id,country,scope,fame_value,fame_change,event_type) VALUES(b.id,city,country_name,'city',(after->>'fame')::int,delta,'festival_performance');INSERT INTO public.band_fame_progression_events(source_type,source_id,performance_outcome_id,subject_type,subject_id,stable_reference,before_state,validated_change,after_state,evidence_digest,rules_version)VALUES('festival_performance',perf.id,lo.id,'band',b.id,p_stable_reference,before,change,after,digest,lo.rules_version)RETURNING id INTO eid; ELSIF (after->>'fame')::int<>coalesce(b.fame,0) THEN PERFORM public._festival_edition_settlement_error('FESTIVAL_EFFECT_CANONICAL_STATE_MISMATCH'); END IF;table_name:='band_fame_progression_events';record_type:='fame_event';
  ELSIF p_kind='member_xp' THEN
   SELECT * INTO profile FROM public.profiles WHERE id=p_subject_id::uuid FOR UPDATE;SELECT a.status INTO attendance FROM public.festival_runtime_band_member_attendance a WHERE a.runtime_performance_id=perf.id AND a.profile_id=profile.id;SELECT bm.user_id INTO member_user FROM public.band_members bm WHERE bm.band_id=perf.band_id AND bm.profile_id=profile.id AND bm.joined_at<=coalesce(perf.actual_start,perf.scheduled_start) AND coalesce(bm.member_status,'active')='active';IF attendance NOT IN('present','late') OR member_user IS NULL THEN PERFORM public._festival_edition_settlement_error('FESTIVAL_EFFECT_MEMBER_NOT_ATTENDING');END IF;
   SELECT id,before_state,validated_change,after_state INTO eid,before,change,after FROM public.member_xp_transactions WHERE stable_reference=p_stable_reference;IF eid IS NULL THEN delta:=least(100,greatest(1,round(score/5)));before:=jsonb_build_object('experience',coalesce(profile.experience,0));change:=jsonb_build_object('xp',delta);after:=jsonb_build_object('experience',coalesce(profile.experience,0)+delta);UPDATE public.profiles SET experience=(after->>'experience')::int WHERE id=profile.id;INSERT INTO public.experience_ledger(user_id,profile_id,activity_type,xp_amount,metadata)VALUES(member_user,profile.id,'gig_performance',delta,jsonb_build_object('stable_reference',p_stable_reference,'performance_outcome_id',lo.id));INSERT INTO public.member_xp_transactions(source_type,source_id,performance_outcome_id,subject_type,subject_id,stable_reference,before_state,validated_change,after_state,evidence_digest,rules_version,user_id)VALUES('festival_performance',perf.id,lo.id,'profile',profile.id,p_stable_reference,before,change,after,digest,lo.rules_version,member_user)RETURNING id INTO eid; ELSIF (after->>'experience')::int<>profile.experience THEN PERFORM public._festival_edition_settlement_error('FESTIVAL_EFFECT_CANONICAL_STATE_MISMATCH');END IF;table_name:='member_xp_transactions';record_type:='xp_transaction';
  ELSIF p_kind IN('song_familiarity','song_popularity') THEN
   song:=p_subject_id::uuid;IF NOT coalesce((lo.evidence->'completedSongIds') ? p_subject_id,false) OR NOT EXISTS(SELECT 1 FROM public.songs s WHERE s.id=song AND (s.band_id=perf.band_id OR s.artist_id=b.leader_id)) THEN PERFORM public._festival_edition_settlement_error('FESTIVAL_EFFECT_SONG_NOT_PERFORMED');END IF;
   SELECT id,before_state,validated_change,after_state INTO eid,before,change,after FROM public.song_performance_progression_events WHERE stable_reference=p_stable_reference;IF eid IS NULL THEN IF p_kind='song_familiarity' THEN SELECT coalesce(familiarity_minutes,0) INTO old_value FROM public.band_song_familiarity WHERE band_id=b.id AND song_id=song FOR UPDATE;old_value:=coalesce(old_value,0);delta:=least(10,greatest(1,round(score/20)));INSERT INTO public.band_song_familiarity(band_id,song_id,familiarity_minutes)VALUES(b.id,song,old_value+delta)ON CONFLICT(band_id,song_id)DO UPDATE SET familiarity_minutes=old_value+delta;ELSE SELECT coalesce(popularity,0) INTO old_value FROM public.songs WHERE id=song FOR UPDATE;delta:=least(10,greatest(0,round((score-50)/10)+(CASE WHEN audience>=1000 THEN 1 ELSE 0 END)));UPDATE public.songs SET popularity=old_value+delta WHERE id=song;END IF;before:=jsonb_build_object('value',old_value);change:=jsonb_build_object('delta',delta);after:=jsonb_build_object('value',old_value+delta);INSERT INTO public.song_performance_progression_events(source_type,source_id,performance_outcome_id,subject_type,subject_id,stable_reference,before_state,validated_change,after_state,evidence_digest,rules_version,progression_type)VALUES('festival_performance',perf.id,lo.id,'song',song,p_stable_reference,before,change,after,digest,lo.rules_version,CASE WHEN p_kind='song_familiarity' THEN 'familiarity' ELSE 'popularity' END)RETURNING id INTO eid;END IF;table_name:='song_performance_progression_events';record_type:=CASE WHEN p_kind='song_familiarity' THEN 'song_familiarity_event' ELSE 'song_popularity_event' END;
  ELSIF p_kind='band_chemistry' THEN
   SELECT id INTO eid FROM public.band_contribution_events WHERE metadata->>'stable_reference'=p_stable_reference;before:=jsonb_build_object('chemistry',coalesce(b.chemistry_level,0));delta:=CASE WHEN score>=75 THEN 1 WHEN score<40 THEN -1 ELSE 0 END;change:=jsonb_build_object('contribution',delta);IF eid IS NULL THEN SELECT a.profile_id INTO song FROM public.festival_runtime_band_member_attendance a WHERE a.runtime_performance_id=perf.id AND a.status IN('present','late') ORDER BY a.profile_id LIMIT 1;INSERT INTO public.band_contribution_events(band_id,profile_id,contribution_type,source_entity_type,source_entity_id,occurred_at,metadata)VALUES(b.id,song,'gig_performance','gig_outcome',lo.id,coalesce(perf.actual_end,now()),jsonb_build_object('stable_reference',p_stable_reference,'source_type','festival_performance','validated_contribution',delta))RETURNING id INTO eid;PERFORM public.recalculate_band_chemistry(b.id);END IF;SELECT chemistry_level INTO old_value FROM public.bands WHERE id=b.id;after:=jsonb_build_object('chemistry',old_value);table_name:='band_contribution_events';record_type:='contribution_event';
  END IF;
 END IF;
 ev:=jsonb_build_object('canonical_record_type',record_type,'canonical_authority',p_authority,'canonical_table_or_service',table_name,'canonical_record_id',eid,'subject_type',p_subject_type,'subject_id',p_subject_id,'stable_reference',p_stable_reference,'before_state',before,'requested_change',coalesce(p_requested_payload,'{}'),'validated_change',change,'after_state',after,'evidence_digest',digest,'rules_version',lo.rules_version,'source_type','festival_performance','source_id',perf.id,'performance_outcome_id',lo.id,'applied_at',now());
 RETURN public._festival_record_authority_result(p_effect_id,p_authority,record_type,eid::text,ev);
END$$;

CREATE OR REPLACE FUNCTION public.apply_festival_performance_result_effect(uuid,uuid,uuid,text,text,text,jsonb) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._apply_live_performance_progression($1,$2,$3,$4,$5,$6,$7,'performance_result','apply_festival_performance_result_effect')$$;
CREATE OR REPLACE FUNCTION public.apply_festival_band_fans_effect(uuid,uuid,uuid,text,text,text,jsonb) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._apply_live_performance_progression($1,$2,$3,$4,$5,$6,$7,'band_fans','apply_festival_band_fans_effect')$$;
CREATE OR REPLACE FUNCTION public.apply_festival_band_fame_effect(uuid,uuid,uuid,text,text,text,jsonb) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._apply_live_performance_progression($1,$2,$3,$4,$5,$6,$7,'band_fame','apply_festival_band_fame_effect')$$;
CREATE OR REPLACE FUNCTION public.apply_festival_member_xp_effect(uuid,uuid,uuid,text,text,text,jsonb) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._apply_live_performance_progression($1,$2,$3,$4,$5,$6,$7,'member_xp','apply_festival_member_xp_effect')$$;
CREATE OR REPLACE FUNCTION public.apply_festival_band_chemistry_effect(uuid,uuid,uuid,text,text,text,jsonb) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._apply_live_performance_progression($1,$2,$3,$4,$5,$6,$7,'band_chemistry','apply_festival_band_chemistry_effect')$$;
CREATE OR REPLACE FUNCTION public.apply_festival_song_familiarity_effect(uuid,uuid,uuid,text,text,text,jsonb) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._apply_live_performance_progression($1,$2,$3,$4,$5,$6,$7,'song_familiarity','apply_festival_song_familiarity_effect')$$;
CREATE OR REPLACE FUNCTION public.apply_festival_song_popularity_effect(uuid,uuid,uuid,text,text,text,jsonb) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._apply_live_performance_progression($1,$2,$3,$4,$5,$6,$7,'song_popularity','apply_festival_song_popularity_effect')$$;
